private struct Tr {
    let zh: String
    let en: String
    let hant: String
    let ja: String
    let ko: String
    let es: String
    let ar: String
    let de: String
    let fr: String
    let he: String
    let pt: String
    let tr: String

    var dict: [String: String] {
        [
            "zh": zh, "en": en, "zh-Hant": hant, "ja": ja, "ko": ko, "es": es,
            "ar": ar, "de": de, "fr": fr, "he": he, "pt": pt, "tr": tr,
        ]
    }
}

enum AppLanguage: String, CaseIterable, Identifiable {
    case system
    case zh
    case zhHant = "zh-Hant"
    case en
    case ja
    case ko
    case es
    case ar
    case de
    case fr
    case he
    case pt
    case tr

    var id: String { rawValue }

    var nativeName: String {
        switch self {
        case .system: return ""
        case .zh: return "简体中文"
        case .zhHant: return "繁體中文"
        case .en: return "English"
        case .ja: return "日本語"
        case .ko: return "한국어"
        case .es: return "Español"
        case .ar: return "العربية"
        case .de: return "Deutsch"
        case .fr: return "Français"
        case .he: return "עברית"
        case .pt: return "Português"
        case .tr: return "Türkçe"
        }
    }

    var isRTL: Bool { self == .ar || self == .he }
}

final class LanguageManager: ObservableObject {
    static let shared = LanguageManager()
    private static let defaultsKey = "settings_language"

    @Published var preference: AppLanguage {
        didSet {
            UserDefaults.standard.set(preference.rawValue, forKey: Self.defaultsKey)
            DailyCalendar.appGroupDefaults.set(preference.rawValue, forKey: Self.defaultsKey)
        }
    }

    private init() {
        let saved = UserDefaults.standard.string(forKey: Self.defaultsKey) ?? AppLanguage.system.rawValue
        preference = AppLanguage(rawValue: saved) ?? .system
        DailyCalendar.appGroupDefaults.set(preference.rawValue, forKey: Self.defaultsKey)
    }

    var resolvedCode: String {
        if preference == .system {
            return resolveLanguageCode(from: Locale.preferredLanguages + Bundle.main.preferredLocalizations)
        }
        return preference.rawValue
    }

    var resolvedLanguage: AppLanguage {
        AppLanguage(rawValue: resolvedCode) ?? .en
    }

    var layoutDirection: LayoutDirection {
        resolvedLanguage.isRTL ? .rightToLeft : .leftToRight
    }

    var locale: Locale {
        switch resolvedCode {
        case "zh": return Locale(identifier: "zh-Hans")
        case "zh-Hant": return Locale(identifier: "zh-Hant")
        default: return Locale(identifier: resolvedCode)
        }
    }
}

func resolveLanguageCode(from candidates: [String]) -> String {
    for raw in candidates {
        let id = raw.replacingOccurrences(of: "_", with: "-").lowercased()
        if id.hasPrefix("zh-hant") || id.hasPrefix("zh-tw") || id.hasPrefix("zh-hk") || id.hasPrefix("zh-mo") {
            return "zh-Hant"
        }
        if id.hasPrefix("zh") { return "zh" }
        if id.hasPrefix("ja") { return "ja" }
        if id.hasPrefix("ko") { return "ko" }
        if id.hasPrefix("es") { return "es" }
        if id.hasPrefix("ar") { return "ar" }
        if id.hasPrefix("de") { return "de" }
        if id.hasPrefix("fr") { return "fr" }
        if id.hasPrefix("he") || id.hasPrefix("iw") { return "he" }
        if id.hasPrefix("pt") { return "pt" }
        if id.hasPrefix("tr") { return "tr" }
        if id.hasPrefix("en") { return "en" }
    }
    return "en"
}

private var currentLanguage: String {
    LanguageManager.shared.resolvedCode
}

private func localizedTemplate(_ key: String) -> String {
    let lang = currentLanguage
    return strings[key]?[lang]
        ?? strings[key]?["en"]
        ?? strings[key]?["zh"]
        ?? key
}

